-- Phase O completion: atomic standing approvals, connected attribution and configuration invalidation.
alter table public.phase_o_agent_configurations add column if not exists permitted_tasks text[] not null default array['MARKET_CONTEXT','EDUCATION','SIGNAL_RECAP','OUTCOME_RECAP','PROOF_CARD','UPGRADE_POST','SOCIAL_EXPORT','CUSTOMER_GUIDANCE'],add column if not exists content_mix jsonb not null default '{}';
alter table public.phase_o_destinations add column if not exists permitted_roles text[] not null default array['CONTENT_PROOF','GROWTH_ENGAGEMENT'],add column if not exists languages text[] not null default array['en','so'],add column if not exists quiet_start time,add column if not exists quiet_end time,add column if not exists quiet_timezone text not null default 'Africa/Nairobi',add column if not exists min_interval_minutes integer not null default 0 check(min_interval_minutes between 0 and 10080);
alter table public.phase_o_approvals add column if not exists used_count integer not null default 0 check(used_count>=0),add column if not exists last_used_at timestamptz,add column if not exists min_interval_minutes integer not null default 0 check(min_interval_minutes between 0 and 10080);
alter table public.phase_o_delivery_parts add column if not exists approval_id uuid references public.phase_o_approvals(id),add column if not exists reservation_token uuid,add column if not exists reservation_expires_at timestamptz;
create table if not exists public.phase_o_approval_uses(id uuid primary key default gen_random_uuid(),approval_id uuid not null references public.phase_o_approvals(id),draft_id uuid not null references public.phase_o_drafts(id),destination_id uuid not null references public.phase_o_destinations(id),reserved_at timestamptz not null default now(),completed_at timestamptz,state text not null check(state in('RESERVED','DELIVERED','UNCERTAIN','FAILED')),unique(approval_id,draft_id));
alter table public.phase_o_approval_uses enable row level security;create policy phase_o_admin_approval_uses on public.phase_o_approval_uses for select to authenticated using(public.is_admin());revoke all on public.phase_o_approval_uses from anon,authenticated;grant select on public.phase_o_approval_uses to authenticated;grant all on public.phase_o_approval_uses to service_role;

create or replace function public.phase_o_binding_hash(p_content_hash text,p_version integer,p_artifact uuid,p_destination uuid,p_offer text) returns text language sql immutable set search_path=public,extensions as $$select encode(extensions.digest(convert_to(concat_ws('|',p_content_hash,p_version::text,coalesce(p_artifact::text,''),coalesce(p_destination::text,''),coalesce(p_offer,'')),'UTF8'),'sha256'),'hex')$$;
create or replace function public.reserve_phase_o_delivery_part(p_draft_id uuid,p_part integer,p_identity text,p_lease_seconds integer default 30) returns jsonb language plpgsql security definer set search_path=public,extensions as $$
declare d phase_o_drafts;a phase_o_approvals;dest phase_o_destinations;j phase_o_agent_jobs;existing phase_o_delivery_parts;use_row phase_o_approval_uses;token uuid:=gen_random_uuid();local_time time;recent integer;is_new boolean:=false;
begin if auth.role()<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED';end if;if p_part<0 or p_lease_seconds not between 5 and 120 then raise exception 'INVALID_RESERVATION_BOUNDS';end if;
 select * into existing from phase_o_delivery_parts where identity=p_identity for update;if found then if existing.state='DELIVERED' then return jsonb_build_object('state','DELIVERED','id',existing.id);elsif existing.state='UNCERTAIN' or(existing.state='RESERVED' and existing.reservation_expires_at<=now()) then if existing.state='RESERVED' then update phase_o_delivery_parts set state='UNCERTAIN',safe_error='RESERVATION_EXPIRED_RECONCILIATION_REQUIRED',updated_at=now() where id=existing.id;end if;return jsonb_build_object('state','UNCERTAIN','id',existing.id);elsif existing.state='RETRY' and coalesce(existing.next_attempt_at,now())<=now() then update phase_o_delivery_parts set state='RESERVED',reservation_token=token,reservation_expires_at=now()+make_interval(secs=>p_lease_seconds),attempt=attempt+1,updated_at=now() where id=existing.id returning * into existing;return jsonb_build_object('state','SEND','id',existing.id,'token',token);else return jsonb_build_object('state','BLOCKED','id',existing.id);end if;end if;
 select * into d from phase_o_drafts where id=p_draft_id;if not found then raise exception 'DRAFT_NOT_FOUND';end if;select * into j from phase_o_agent_jobs where id=d.job_id;if not found then raise exception 'JOB_NOT_FOUND';end if;select * into a from phase_o_approvals where draft_id=d.id and revoked_at is null order by approved_at desc limit 1 for update;if not found or a.expires_at is null or a.expires_at<=now() then raise exception 'CURRENT_BOUND_APPROVAL_REQUIRED';end if;if a.draft_version<>d.version or a.binding_hash<>phase_o_binding_hash(d.content_hash,d.version,d.artifact_id,d.destination_id,d.offer_code) then raise exception 'APPROVAL_BINDING_MISMATCH';end if;
 select * into dest from phase_o_destinations where id=d.destination_id for update;if not found or not dest.enabled or dest.configuration_state<>'READY' or dest.permission_verified_at is null then raise exception 'DESTINATION_NOT_CURRENTLY_ELIGIBLE';end if;if not(j.role=any(dest.permitted_roles)) or not(j.language=any(dest.languages)) or not(j.content_type=any(dest.allowed_content_types)) then raise exception 'DESTINATION_PERMISSION_REJECTED';end if;local_time:=(now() at time zone dest.quiet_timezone)::time;if dest.quiet_start is not null and dest.quiet_end is not null and(case when dest.quiet_start<dest.quiet_end then local_time>=dest.quiet_start and local_time<dest.quiet_end else local_time>=dest.quiet_start or local_time<dest.quiet_end end)then raise exception 'DESTINATION_QUIET_HOURS';end if;
 insert into phase_o_approval_uses(approval_id,draft_id,destination_id,state)values(a.id,d.id,dest.id,'RESERVED')on conflict(approval_id,draft_id)do nothing returning * into use_row;is_new:=found;if is_new then if a.used_count>=a.max_uses then raise exception 'APPROVAL_MAX_USES_EXHAUSTED';end if;if a.last_used_at is not null and a.last_used_at+make_interval(mins=>greatest(a.min_interval_minutes,dest.min_interval_minutes))>now() then raise exception 'APPROVAL_FREQUENCY_LIMIT';end if;select count(distinct u.id)into recent from phase_o_approval_uses u where u.destination_id=dest.id and u.reserved_at>now()-interval '1 hour';if recent>dest.max_per_hour then raise exception 'DESTINATION_RATE_LIMIT';end if;update phase_o_approvals set used_count=used_count+1,last_used_at=now() where id=a.id;end if;
 insert into phase_o_delivery_parts(draft_id,part,identity,state,attempt,approval_id,reservation_token,reservation_expires_at)values(d.id,p_part,p_identity,'RESERVED',1,a.id,token,now()+make_interval(secs=>p_lease_seconds))returning * into existing;return jsonb_build_object('state','SEND','id',existing.id,'token',token);end$$;
create or replace function public.finish_phase_o_delivery_part(p_id uuid,p_token uuid,p_state text,p_message_id text default null,p_error text default null,p_next_attempt_at timestamptz default null)returns boolean language plpgsql security definer set search_path=public as $$declare changed integer;use_id uuid;begin if auth.role()<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED';end if;if p_state not in('DELIVERED','RETRY','DEAD','UNCERTAIN')then raise exception 'INVALID_DELIVERY_STATE';end if;update phase_o_delivery_parts set state=p_state,provider_message_id=p_message_id,safe_error=left(p_error,240),next_attempt_at=p_next_attempt_at,reservation_token=null,reservation_expires_at=null,updated_at=now() where id=p_id and state='RESERVED' and reservation_token=p_token and reservation_expires_at>now() returning approval_id into use_id;get diagnostics changed=row_count;if changed=1 and p_state in('DELIVERED','UNCERTAIN')then update phase_o_approval_uses set state=p_state,completed_at=case when p_state='DELIVERED'then now()else null end where approval_id=use_id and draft_id=(select draft_id from phase_o_delivery_parts where id=p_id);end if;return changed=1;end$$;
revoke all on function public.phase_o_binding_hash(text,integer,uuid,uuid,text),public.reserve_phase_o_delivery_part(uuid,integer,text,integer),public.finish_phase_o_delivery_part(uuid,uuid,text,text,text,timestamptz) from public,anon,authenticated;grant execute on function public.reserve_phase_o_delivery_part(uuid,integer,text,integer),public.finish_phase_o_delivery_part(uuid,uuid,text,text,text,timestamptz) to service_role;

create or replace function public.phase_o_invalidate_approvals()returns trigger language plpgsql set search_path=public as $$begin if tg_table_name='phase_o_destinations'then update phase_o_approvals a set revoked_at=now()from phase_o_drafts d where d.destination_id=new.id and a.draft_id=d.id and a.revoked_at is null;elsif tg_table_name='phase_o_campaigns'then update phase_o_approvals a set revoked_at=now()from phase_o_drafts d join phase_o_agent_jobs j on j.id=d.job_id where j.campaign_id=new.id and a.draft_id=d.id and a.revoked_at is null;end if;return new;end$$;
drop trigger if exists trg_phase_o_destination_invalidate on public.phase_o_destinations;create trigger trg_phase_o_destination_invalidate after update of audience,enabled,allowed_content_types,max_per_hour,permitted_roles,languages,quiet_start,quiet_end,quiet_timezone,min_interval_minutes on public.phase_o_destinations for each row when(old is distinct from new)execute function public.phase_o_invalidate_approvals();
drop trigger if exists trg_phase_o_campaign_invalidate on public.phase_o_campaigns;create trigger trg_phase_o_campaign_invalidate after update of canonical_url,offer_code,status on public.phase_o_campaigns for each row when(old is distinct from new)execute function public.phase_o_invalidate_approvals();

create or replace function public.record_phase_o_attribution(p_event text,p_key text,p_customer uuid,p_campaign_text text,p_audience text,p_source text,p_occurred timestamptz default now())returns void language plpgsql security definer set search_path=public as $$declare cid uuid;begin select id into cid from phase_o_campaigns where id::text=p_campaign_text or source_code=p_campaign_text limit 1;insert into phase_o_attribution_events(customer_id,campaign_id,event_type,audience,occurred_at,source_ref,idempotency_key)values(p_customer,cid,p_event,p_audience,p_occurred,p_source,p_key)on conflict(idempotency_key)do nothing;end$$;
create or replace function public.phase_o_attribute_campaign()returns trigger language plpgsql security definer set search_path=public as $$begin perform record_phase_o_attribution(case when new.conversion_stage='LANDING'then'LANDING_VISIT'else'CLICK'end,'campaign-attribution:'||new.id,new.customer_id,new.campaign_id,null,'campaign_attributions',new.clicked_at);return new;end$$;
create or replace function public.phase_o_attribute_checkout()returns trigger language plpgsql security definer set search_path=public as $$begin perform record_phase_o_attribution('CHECKOUT_ATTEMPT','checkout:'||new.id,new.customer_id,new.campaign,null,'commerce_checkout_sessions',new.created_at);return new;end$$;
create or replace function public.phase_o_attribute_entitlement()returns trigger language plpgsql security definer set search_path=public as $$declare ev text;campaign text;begin if new.product_code<>'VIP_SIGNALS'then return new;end if;if new.state in('ACTIVE','TRIAL','GRACE')then ev:=case when tg_op='UPDATE'and old.state in('ACTIVE','TRIAL','GRACE')and new.valid_until is distinct from old.valid_until then'RENEWED'else'ENTITLEMENT_VERIFIED'end;else ev:='CHURNED';end if;select c.campaign into campaign from commerce_checkout_sessions c where c.customer_id=new.customer_id and c.product_code='VIP_SIGNALS' order by c.created_at desc limit 1;perform record_phase_o_attribution(ev,'entitlement:'||new.id||':'||ev||':'||coalesce(new.valid_until::text,new.state),new.customer_id,campaign,null,'phase_h_entitlements',new.updated_at);return new;end$$;
create or replace function public.phase_o_attribute_telegram_link()returns trigger language plpgsql security definer set search_path=public as $$begin if new.telegram_user_id is not null then perform record_phase_o_attribution('TELEGRAM_LINKED','telegram-link:'||new.id||':'||new.updated_at,new.user_id,null,null,'telegram_links',new.updated_at);end if;return new;end$$;
create or replace function public.phase_o_attribute_membership()returns trigger language plpgsql security definer set search_path=public as $$begin if new.state='ACTIVE'then perform record_phase_o_attribution('MEMBERSHIP_CONFIRMED','membership:'||new.id||':'||new.updated_at,new.customer_id,null,new.audience,'telegram_memberships',new.updated_at);end if;return new;end$$;
drop trigger if exists trg_phase_o_attr_campaign on public.campaign_attributions;create trigger trg_phase_o_attr_campaign after insert on public.campaign_attributions for each row execute function public.phase_o_attribute_campaign();drop trigger if exists trg_phase_o_attr_checkout on public.commerce_checkout_sessions;create trigger trg_phase_o_attr_checkout after insert on public.commerce_checkout_sessions for each row execute function public.phase_o_attribute_checkout();drop trigger if exists trg_phase_o_attr_entitlement on public.phase_h_entitlements;create trigger trg_phase_o_attr_entitlement after insert or update of state,valid_until on public.phase_h_entitlements for each row execute function public.phase_o_attribute_entitlement();drop trigger if exists trg_phase_o_attr_link on public.telegram_links;create trigger trg_phase_o_attr_link after insert or update of telegram_user_id on public.telegram_links for each row execute function public.phase_o_attribute_telegram_link();drop trigger if exists trg_phase_o_attr_membership on public.telegram_memberships;create trigger trg_phase_o_attr_membership after insert or update of state on public.telegram_memberships for each row execute function public.phase_o_attribute_membership();
alter table public.phase_o_attribution_events drop constraint if exists phase_o_attribution_events_event_type_check;alter table public.phase_o_attribution_events add constraint phase_o_attribution_events_event_type_check check(event_type in('LANDING_VISIT','CLICK','SIGNUP','ENROLLMENT','CHECKOUT_ATTEMPT','ENTITLEMENT_VERIFIED','TELEGRAM_LINKED','MEMBERSHIP_CONFIRMED','RENEWED','CHURNED'));
create or replace function public.record_phase_o_attribution(p_event text,p_key text,p_customer uuid,p_campaign_text text,p_audience text,p_source text,p_occurred timestamptz default now())returns void language plpgsql security definer set search_path=public as $$declare cid uuid;begin select id into cid from phase_o_campaigns where id::text=p_campaign_text or source_code=p_campaign_text limit 1;if cid is null and p_customer is not null then select pc.id into cid from commerce_checkout_sessions c join phase_o_campaigns pc on pc.id::text=c.campaign or pc.source_code=c.campaign where c.customer_id=p_customer order by c.created_at desc limit 1;end if;insert into phase_o_attribution_events(customer_id,campaign_id,event_type,audience,occurred_at,source_ref,idempotency_key)values(p_customer,cid,p_event,p_audience,p_occurred,p_source,p_key)on conflict(idempotency_key)do nothing;end$$;
create or replace function public.phase_o_attribute_signup()returns trigger language plpgsql security definer set search_path=public as $$begin perform record_phase_o_attribution('SIGNUP','signup:'||new.id,new.id,null,null,'profiles',coalesce(new.created_at,now()));return new;end$$;
drop trigger if exists trg_phase_o_attr_signup on public.profiles;create trigger trg_phase_o_attr_signup after insert on public.profiles for each row execute function public.phase_o_attribute_signup();
create or replace function public.phase_o_attribute_entitlement()returns trigger language plpgsql security definer set search_path=public as $$declare ev text;campaign text;begin if new.product_code='FREE_SIGNALS'and new.state in('ACTIVE','TRIAL','GRACE')then ev:='ENROLLMENT';elsif new.product_code='VIP_SIGNALS'and new.state in('ACTIVE','TRIAL','GRACE')then ev:=case when tg_op='UPDATE'and old.state in('ACTIVE','TRIAL','GRACE')and new.valid_until is distinct from old.valid_until then'RENEWED'else'ENTITLEMENT_VERIFIED'end;elsif new.product_code='VIP_SIGNALS'then ev:='CHURNED';else return new;end if;select c.campaign into campaign from commerce_checkout_sessions c where c.customer_id=new.customer_id and c.product_code=new.product_code order by c.created_at desc limit 1;perform record_phase_o_attribution(ev,'entitlement:'||new.id||':'||ev||':'||coalesce(new.valid_until::text,new.state),new.customer_id,campaign,null,'phase_h_entitlements',new.updated_at);return new;end$$;
create or replace view public.phase_o_funnel_safe with(security_invoker=true)as select campaign_id,count(*)filter(where event_type='LANDING_VISIT')landing_visits,count(*)filter(where event_type='CLICK')clicks,count(distinct customer_id)filter(where event_type='SIGNUP')signups,count(distinct customer_id)filter(where event_type='CHECKOUT_ATTEMPT')checkout_attempts,count(distinct customer_id)filter(where event_type='ENTITLEMENT_VERIFIED')paid_vip_customers,count(distinct customer_id)filter(where event_type='MEMBERSHIP_CONFIRMED'and audience='FREE')free_members,count(distinct customer_id)filter(where event_type='MEMBERSHIP_CONFIRMED'and audience='VIP_FOREX_GOLD')vip_forex_gold_members,count(distinct customer_id)filter(where event_type='MEMBERSHIP_CONFIRMED'and audience='VIP_CRYPTO')vip_crypto_members,count(distinct customer_id)filter(where event_type='ENROLLMENT')enrollments,count(distinct customer_id)filter(where event_type='RENEWED')renewals,count(distinct customer_id)filter(where event_type='CHURNED')churned from phase_o_attribution_events group by campaign_id;
alter table public.phase_o_approval_uses add column if not exists use_key text;
update public.phase_o_approval_uses set use_key=draft_id::text where use_key is null;
alter table public.phase_o_approval_uses alter column use_key set not null;
alter table public.phase_o_approval_uses drop constraint if exists phase_o_approval_uses_approval_id_draft_id_key;
create unique index if not exists phase_o_approval_use_key on public.phase_o_approval_uses(approval_id,use_key);
-- Rebind reservation to delivery occurrence rather than draft, so standing approvals count each schedule once while multipart/retries share one use.
create or replace function public.reserve_phase_o_delivery_part(p_draft_id uuid,p_part integer,p_identity text,p_lease_seconds integer default 30) returns jsonb language plpgsql security definer set search_path=public,extensions as $$
declare d phase_o_drafts;a phase_o_approvals;dest phase_o_destinations;j phase_o_agent_jobs;existing phase_o_delivery_parts;use_row phase_o_approval_uses;token uuid:=gen_random_uuid();local_time time;recent integer;is_new boolean:=false;use_key text:=regexp_replace(p_identity,':p[0-9]+$','');
begin if auth.role()<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED';end if;if p_part<0 or p_lease_seconds not between 5 and 120 then raise exception 'INVALID_RESERVATION_BOUNDS';end if;select * into existing from phase_o_delivery_parts where identity=p_identity for update;if found then if existing.state='DELIVERED'then return jsonb_build_object('state','DELIVERED','id',existing.id);elsif existing.state='UNCERTAIN'or(existing.state='RESERVED'and existing.reservation_expires_at<=now())then if existing.state='RESERVED'then update phase_o_delivery_parts set state='UNCERTAIN',safe_error='RESERVATION_EXPIRED_RECONCILIATION_REQUIRED',updated_at=now()where id=existing.id;end if;return jsonb_build_object('state','UNCERTAIN','id',existing.id);elsif existing.state='RETRY'and coalesce(existing.next_attempt_at,now())<=now()then update phase_o_delivery_parts set state='RESERVED',reservation_token=token,reservation_expires_at=now()+make_interval(secs=>p_lease_seconds),attempt=attempt+1,updated_at=now()where id=existing.id returning * into existing;return jsonb_build_object('state','SEND','id',existing.id,'token',token);else return jsonb_build_object('state','BLOCKED','id',existing.id);end if;end if;select * into d from phase_o_drafts where id=p_draft_id;if not found then raise exception 'DRAFT_NOT_FOUND';end if;select * into j from phase_o_agent_jobs where id=d.job_id;if not found then raise exception 'JOB_NOT_FOUND';end if;select * into a from phase_o_approvals where draft_id=d.id and revoked_at is null order by approved_at desc limit 1 for update;if not found or a.expires_at is null or a.expires_at<=now()then raise exception 'CURRENT_BOUND_APPROVAL_REQUIRED';end if;if a.draft_version<>d.version or a.binding_hash<>phase_o_binding_hash(d.content_hash,d.version,d.artifact_id,d.destination_id,d.offer_code)then raise exception 'APPROVAL_BINDING_MISMATCH';end if;select * into dest from phase_o_destinations where id=d.destination_id for update;if not found or not dest.enabled or dest.configuration_state<>'READY'or dest.permission_verified_at is null then raise exception 'DESTINATION_NOT_CURRENTLY_ELIGIBLE';end if;if not(j.role=any(dest.permitted_roles))or not(j.language=any(dest.languages))or not(j.content_type=any(dest.allowed_content_types))then raise exception 'DESTINATION_PERMISSION_REJECTED';end if;local_time:=(now()at time zone dest.quiet_timezone)::time;if dest.quiet_start is not null and dest.quiet_end is not null and(case when dest.quiet_start<dest.quiet_end then local_time>=dest.quiet_start and local_time<dest.quiet_end else local_time>=dest.quiet_start or local_time<dest.quiet_end end)then raise exception 'DESTINATION_QUIET_HOURS';end if;insert into phase_o_approval_uses(approval_id,draft_id,destination_id,state,use_key)values(a.id,d.id,dest.id,'RESERVED',use_key)on conflict(approval_id,use_key)do nothing returning * into use_row;is_new:=found;if is_new then if a.used_count>=a.max_uses then raise exception 'APPROVAL_MAX_USES_EXHAUSTED';end if;if a.last_used_at is not null and a.last_used_at+make_interval(mins=>greatest(a.min_interval_minutes,dest.min_interval_minutes))>now()then raise exception 'APPROVAL_FREQUENCY_LIMIT';end if;select count(distinct u.id)into recent from phase_o_approval_uses u where u.destination_id=dest.id and u.reserved_at>now()-interval '1 hour';if recent>dest.max_per_hour then raise exception 'DESTINATION_RATE_LIMIT';end if;update phase_o_approvals set used_count=used_count+1,last_used_at=now()where id=a.id;end if;insert into phase_o_delivery_parts(draft_id,part,identity,state,attempt,approval_id,reservation_token,reservation_expires_at)values(d.id,p_part,p_identity,'RESERVED',1,a.id,token,now()+make_interval(secs=>p_lease_seconds))returning * into existing;return jsonb_build_object('state','SEND','id',existing.id,'token',token);end$$;
create or replace function public.persist_phase_o_draft(p_job_id uuid,p_content text,p_content_hash text,p_artifact_id uuid,p_destination_id uuid,p_offer_code text,p_usage_units integer,p_model text)returns public.phase_o_drafts language plpgsql security definer set search_path=public as $$declare j phase_o_agent_jobs;cfg phase_o_agent_configurations;c phase_o_campaigns;used bigint;version integer;result phase_o_drafts;begin if auth.role()<>'service_role'then raise exception 'SERVICE_ROLE_REQUIRED';end if;if p_usage_units<0 then raise exception 'INVALID_USAGE';end if;select * into j from phase_o_agent_jobs where id=p_job_id for update;if not found then raise exception 'JOB_NOT_FOUND';end if;select * into cfg from phase_o_agent_configurations where role=j.role for update;if not cfg.enabled or cfg.paused_at is not null then raise exception 'AGENT_ROLE_DISABLED';end if;select coalesce(sum(usage_units),0)into used from phase_o_usage where role=j.role and created_at>=date_trunc('month',now());if used+p_usage_units>cfg.monthly_budget_units then raise exception 'AGENT_BUDGET_EXHAUSTED';end if;if j.campaign_id is not null then select * into c from phase_o_campaigns where id=j.campaign_id for update;if not found or c.status not in('DRAFT','ACTIVE')then raise exception 'CAMPAIGN_NOT_ELIGIBLE';end if;if c.spent_units+p_usage_units>c.budget_units then raise exception 'CAMPAIGN_BUDGET_EXHAUSTED';end if;update phase_o_campaigns set spent_units=spent_units+p_usage_units,updated_at=now()where id=c.id;end if;select coalesce(max(d.version),0)+1 into version from phase_o_drafts d where d.job_id=j.id;insert into phase_o_drafts(job_id,version,content,content_hash,artifact_id,destination_id,offer_code,usage_units)values(j.id,version,p_content,p_content_hash,p_artifact_id,p_destination_id,p_offer_code,p_usage_units)returning * into result;insert into phase_o_usage(job_id,campaign_id,role,model,usage_units)values(j.id,j.campaign_id,j.role,p_model,p_usage_units);return result;end$$;
revoke all on function public.persist_phase_o_draft(uuid,text,text,uuid,uuid,text,integer,text)from public,anon,authenticated;grant execute on function public.persist_phase_o_draft(uuid,text,text,uuid,uuid,text,integer,text)to service_role;
revoke all on function public.record_phase_o_attribution(text,text,uuid,text,text,text,timestamptz),public.phase_o_attribute_campaign(),public.phase_o_attribute_checkout(),public.phase_o_attribute_entitlement(),public.phase_o_attribute_telegram_link(),public.phase_o_attribute_membership(),public.phase_o_attribute_signup(),public.phase_o_invalidate_approvals() from public,anon,authenticated;
grant execute on function public.record_phase_o_attribution(text,text,uuid,text,text,text,timestamptz) to service_role;
create or replace function public.finish_phase_o_delivery_part(p_id uuid,p_token uuid,p_state text,p_message_id text default null,p_error text default null,p_next_attempt_at timestamptz default null)returns boolean language plpgsql security definer set search_path=public as $$declare changed integer;part phase_o_delivery_parts;begin if auth.role()<>'service_role'then raise exception 'SERVICE_ROLE_REQUIRED';end if;if p_state not in('DELIVERED','RETRY','DEAD','UNCERTAIN')then raise exception 'INVALID_DELIVERY_STATE';end if;update phase_o_delivery_parts set state=p_state,provider_message_id=p_message_id,safe_error=left(p_error,240),next_attempt_at=p_next_attempt_at,reservation_token=null,reservation_expires_at=null,updated_at=now()where id=p_id and state='RESERVED'and reservation_token=p_token and reservation_expires_at>now()returning * into part;get diagnostics changed=row_count;if changed=1 and p_state in('DELIVERED','UNCERTAIN')then update phase_o_approval_uses set state=p_state,completed_at=case when p_state='DELIVERED'then now()else null end where approval_id=part.approval_id and use_key=regexp_replace(part.identity,':p[0-9]+$','');end if;return changed=1;end$$;
